function calculateMMR(baseRR, streak, isMVP) {
    let total = baseRR;
    // Użyj klawisza Tab do wcięć w kodzie!
    if (streak >= 3) {
        total += (streak - 2) * 5;
    }
    if (isMVP) {
        total += 10;
    }
    return total;
}

