function getTopNicknames(players) {
    return players
        .{{0}}(p => p.mmr >= 1500)
        .{{1}}((a, b) => b.mmr - a.mmr)
        .{{2}}(p => p.nickname);
}

using System.Linq;
using System.Collections.Generic;

public class Matchmaker
{
    public List<Player> FindReadyQueue(IEnumerable<Player> players)
    {
        return players
            .{{0}}(p => p.IsReady)
            .{{1}}(p => p.MMR)
            .{{2}}();
    }
}

